type EntitySettlementBaseType = {
  resource: string
  id: string
  createdAt?: z.infer<typeof CreatedAtSchema>
  reference?: string | null
  settledAt?: string | null
  status: z.infer<typeof SettlementStatusSchema>
  amount: z.infer<typeof AmountSchema> & unknown
  balanceId: z.infer<typeof BalanceTokenSchema>
  invoiceId?: z.infer<typeof InvoiceTokenSchema> | null
  periods?: {
    [key: string]: {
      [key: string]: {
        costs?: {
          description: string
          method: z.infer<typeof SettlementMethodSchema>
          count: number
          rate: { fixed: z.infer<typeof AmountNullableSchema>; percentage: string | null }
          amountNet: z.infer<typeof AmountSchema>
          amountVat: z.infer<typeof AmountNullableSchema>
          amountGross: z.infer<typeof AmountSchema>
        }[]
        revenue?: {
          description: string
          method: z.infer<typeof SettlementMethodSchema>
          count: number
          amountNet: z.infer<typeof AmountSchema>
          amountVat: z.infer<typeof AmountNullableSchema>
          amountGross: z.infer<typeof AmountSchema>
        }[]
        invoiceId?: z.infer<typeof InvoiceTokenSchema> | null
        invoiceReference?: string | null
      }
    }
  }
  _links: { [key: string]: unknown }
}

const EntitySettlementBaseSchema: z.ZodType<EntitySettlementBaseType> = z
  .object({
    resource: z
      .string()
      .openapi({
        description:
          'Indicates the response contains a settlement object. Will always contain the string `settlement` for this\nendpoint.',
        readOnly: true,
        example: 'settlement',
      }),
    id: z
      .string()
      .openapi({
        description: 'The identifier uniquely referring to this settlement.',
        readOnly: true,
        example: 'stl_5B8cwPMGnU',
      }),
    createdAt: CreatedAtSchema.exactOptional(),
    reference: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          "The settlement's bank reference, as found in your Mollie account and on your bank statement.",
        readOnly: true,
        example: '07049691.2406.01',
      }),
    settledAt: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'The date on which the settlement was settled, in ISO 8601 format.\n\nFor an [open settlement](get-open-settlement) or for the [next settlement](get-next-settlement), no settlement\ndate is available.',
        readOnly: true,
        example: '2025-03-31T12:54:39+00:00',
      }),
    status: SettlementStatusSchema.openapi({ readOnly: true }),
    amount: AmountSchema.openapi({
      description: 'The total amount of the settlement.',
      readOnly: true,
    }),
    balanceId: BalanceTokenSchema.openapi({
      description: 'The balance token that the settlement was settled to.',
      readOnly: true,
    }),
    invoiceId: InvoiceTokenSchema.nullable()
      .exactOptional()
      .openapi({
        description:
          'The ID of the oldest invoice created for all the periods, if the invoice has been created yet.',
        readOnly: true,
      }),
    periods: z
      .record(
        z.string(),
        z.record(
          z.string(),
          z
            .object({
              costs: z
                .array(
                  z
                    .object({
                      description: z
                        .string()
                        .openapi({
                          description: 'A description of the cost subtotal',
                          example: 'Credit card - Visa debit consumer domestic',
                        }),
                      method: SettlementMethodSchema,
                      count: z.int().openapi({ description: 'The number of fees', example: 10 }),
                      rate: z
                        .object({
                          fixed: AmountNullableSchema,
                          percentage: z.string().nullable().openapi({ example: '2.5' }),
                        })
                        .openapi({
                          description:
                            'The service rates, further divided into `fixed` and `percentage` costs.\n\nFor pass-through fees, which are charged by an external party rather than at an agreed Mollie\nrate, both `fixed` and `percentage` are `null`.',
                          required: ['fixed', 'percentage'],
                        }),
                      amountNet: AmountSchema.openapi({
                        description: 'The net total cost, i.e. excluding VAT',
                      }),
                      amountVat: AmountNullableSchema.openapi({
                        description: 'The applicable VAT',
                      }),
                      amountGross: AmountSchema.openapi({
                        description: 'The gross total cost, i.e. including VAT',
                      }),
                    })
                    .openapi({
                      required: [
                        'description',
                        'method',
                        'count',
                        'rate',
                        'amountNet',
                        'amountVat',
                        'amountGross',
                      ],
                    }),
                )
                .exactOptional()
                .openapi({
                  description:
                    'An array of cost objects, describing the fees withheld for each payment method during this period.',
                }),
              revenue: z
                .array(
                  z
                    .object({
                      description: z
                        .string()
                        .openapi({
                          description: 'A description of the revenue subtotal',
                          example: 'Credit card',
                        }),
                      method: SettlementMethodSchema,
                      count: z
                        .int()
                        .openapi({ description: 'The number of payments', example: 10 }),
                      amountNet: AmountSchema.openapi({
                        description: 'The net total of received funds, i.e. excluding VAT',
                      }),
                      amountVat: AmountNullableSchema.openapi({
                        description: 'The applicable VAT',
                      }),
                      amountGross: AmountSchema.openapi({
                        description: 'The gross total of received funds, i.e. including VAT',
                      }),
                    })
                    .openapi({
                      required: [
                        'description',
                        'method',
                        'count',
                        'amountNet',
                        'amountVat',
                        'amountGross',
                      ],
                    }),
                )
                .exactOptional()
                .openapi({
                  description:
                    'An array of revenue objects containing the total revenue for each payment method during this period.',
                }),
              invoiceId: InvoiceTokenSchema.nullable()
                .exactOptional()
                .openapi({
                  description:
                    'The ID of the invoice created for this period, if the invoice has been created already.',
                }),
              invoiceReference: z
                .string()
                .nullable()
                .exactOptional()
                .openapi({
                  description: 'The invoice reference, if the invoice has been created already.',
                  example: 'MOLR2021.0001399669',
                }),
            })
            .openapi({ required: [] }),
        ),
      )
      .exactOptional()
      .openapi({
        description:
          'For bookkeeping purposes, the settlement includes an overview of transactions included in the settlement. These\ntransactions are grouped into \'period\' objects — one for each calendar month.\n\nFor example, if a settlement includes funds from 15 April until 4 May, it will include two period objects. One for\nall transactions processed between 15 April and 30 April, and one for all transactions between 1 May and 4 May.\n\nPeriod objects are grouped by year, and then by month. So in the above example, the full `periods` collection will\nlook as follows: `{"2024": {"04": {...}, "05": {...}}}`. The year and month in this documentation are referred as `<year>` and `<month>`.\n\nThe example response should give a good idea of what this looks like in practise.',
        readOnly: true,
      }),
    _links: z
      .looseObject({})
      .openapi({
        description:
          'An object with several relevant URLs. Every URL object will contain an `href` and a `type` field.',
        readOnly: true,
      }),
  })
  .openapi({ required: ['resource', 'id', 'status', 'amount', 'balanceId', '_links'] })
  .openapi('EntitySettlementBase')

