const LineCategoriesResponseSchema = z
  .enum(['eco', 'gift', 'meal', 'sport_culture', 'additional', 'consume'])
  .openapi({ example: 'eco', 'x-speakeasy-unknown-values': 'allow' })
  .openapi('LineCategoriesResponse')

const PaymentLineItemResponseSchema = z
  .object({
    type: PaymentLineTypeResponseSchema.exactOptional(),
    description: z
      .string()
      .openapi({
        description:
          'A description of the line item. For example *LEGO 4440 Forest Police Station*.',
        example: 'LEGO 4440 Forest Police Station',
      }),
    quantity: z.int().min(1).openapi({ description: 'The number of items.', example: 1 }),
    quantityUnit: z
      .string()
      .exactOptional()
      .openapi({
        description: 'The unit for the quantity. For example *pcs*, *kg*, or *cm*.',
        example: 'pcs',
      }),
    unitPrice: AmountSchema.openapi({
      description:
        'The price of a single item including VAT.\n\nFor example: `{"currency":"EUR", "value":"89.00"}` if the box of LEGO costs €89.00 each.\n\nFor types `discount`, `store_credit`, and `gift_card`, the unit price must be negative.\n\nThe unit price can be zero in case of free items.',
    }),
    discountAmount: AmountSchema.exactOptional().openapi({
      description:
        'Any line-specific discounts, as a positive amount. Not relevant if the line itself is already a discount\ntype.',
    }),
    totalAmount: AmountSchema.openapi({
      description:
        'The total amount of the line, including VAT and discounts.\n\nShould match the following formula: `(unitPrice × quantity) - discountAmount`.\n\nThe sum of all `totalAmount` values of all order lines should be equal to the full payment amount.',
    }),
    vatRate: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The VAT rate applied to the line, for example `21.00` for 21%. The vatRate should be passed as a string and\nnot as a float, to ensure the correct number of decimals are passed.',
        example: '21.00',
      }),
    vatAmount: AmountSchema.exactOptional().openapi({
      description:
        'The amount of value-added tax on the line. The `totalAmount` field includes VAT, so the `vatAmount` can be\ncalculated with the formula `totalAmount × (vatRate / (100 + vatRate))`.\n\nAny deviations from this will result in an error.\n\nFor example, for a `totalAmount` of SEK 100.00 with a 25.00% VAT rate, we expect a VAT amount of\n`SEK 100.00 × (25 / 125) = SEK 20.00`.',
    }),
    sku: z
      .string()
      .max(64)
      .exactOptional()
      .openapi({
        description: 'The SKU, EAN, ISBN or UPC of the product sold.',
        example: '9780241661628',
      }),
    categories: z
      .array(LineCategoriesResponseSchema)
      .exactOptional()
      .openapi({
        description:
          'An array with the voucher categories, in case of a line eligible for a voucher. See the\n[Integrating Vouchers](https://docs.mollie.com/docs/integrating-vouchers/) guide for more information.',
        example: ['meal', 'eco'],
      }),
    imageUrl: z
      .string()
      .exactOptional()
      .openapi({
        description: 'A link pointing to an image of the product sold.',
        example: 'https://...',
      }),
    productUrl: z
      .string()
      .exactOptional()
      .openapi({
        description: 'A link pointing to the product page in your web shop of the product sold.',
        example: 'https://...',
      }),
  })
  .openapi({ required: ['description', 'quantity', 'unitPrice', 'totalAmount'] })
  .openapi('PaymentLineItemResponse')

