const EntityTransferSchema = z
  .object({
    resource: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Indicates the response contains a transfer object. Will always contain the string `business-account-transfer`\nfor this endpoint.',
        readOnly: true,
        example: 'business-account-transfer',
      }),
    id: BusinessAccountTransferTokenSchema.exactOptional().openapi({
      description:
        'The identifier uniquely referring to this transfer. Mollie assigns this identifier at transfer creation time.',
      readOnly: true,
    }),
    mode: ModeSchema.exactOptional(),
    debtorIban: z
      .string()
      .exactOptional()
      .openapi({
        description:
          "The IBAN of the debtor's (sender) Mollie account from which to initiate the transfer.",
        example: 'NL55MLLE0123456789',
        writeOnly: true,
      }),
    debtor: TransferPartySchema.exactOptional().openapi({
      description: 'The debtor (sender) of the transfer, including their name and account details.',
      readOnly: true,
    }),
    creditor: TransferPartySchema.exactOptional().openapi({
      description:
        'The creditor (recipient) of the transfer, including their name and account details.',
    }),
    amount: AmountSchema.exactOptional().openapi({
      description:
        'The amount of the transfer, e.g. `{"currency":"EUR", "value":"100.00"}` if you would want to transfer €100.00.\n\nOnly `EUR` is supported for SEPA transfers.',
    }),
    description: z
      .string()
      .regex(/^(?![:\-]$)(?!.*(--|::))([a-zA-Z0-9]+[\s]*[a-zA-Z0-9\/\-?:().,'+_ ]*)?$/)
      .max(140)
      .nullable()
      .exactOptional()
      .openapi({
        description:
          "A short description of the transfer. This will appear on the bank statement of both the debtor and creditor.\n\nIt must begin with an alphanumeric character, followed by any combination of letters, numbers, spaces or special characters `/ - ? : ( ) . , ' + _`.\n\nConstraints:\n- Cannot be solely a hyphen (-) or colon (:)\n- Cannot contain consecutive hyphens (--)\n- Cannot contain consecutive colons (::)",
        example: 'Invoice 12345',
      }),
    businessAccountTransactionId: BusinessAccountTransactionTokenSchema.exactOptional().openapi({
      description:
        'The identifier of the corresponding transaction in the business accounts transaction resource.',
      readOnly: true,
    }),
    transferScheme: TransferSchemeSchema.exactOptional(),
    creditDebitIndicator: CreditDebitIndicatorSchema.exactOptional(),
    status: TransferStatusSchema.exactOptional(),
    statusHistory: z
      .array(StatusHistoryEntrySchema)
      .exactOptional()
      .openapi({
        description: 'A chronological list of status transitions the transfer has gone through.',
        readOnly: true,
      }),
    createdAt: CreatedAtSchema.exactOptional(),
    statusReason: StatusReason_2Schema.exactOptional(),
    metadata: MetadataSchema.exactOptional(),
    testmode: TestmodeCreateSchema.exactOptional(),
  })
  .openapi({ required: [] })
  .openapi('EntityTransfer')

