const ListLimitParamsSchema = z
  .preprocess(
    (val) => (val === 'null' ? null : val),
    z
      .preprocess(
        (val) =>
          typeof val === 'string' &&
          /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
          (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
            ? Number(val)
            : val,
        z.int().min(1).max(250),
      )
      .nullable(),
  )
  .exactOptional()
  .openapi({
    param: {
      name: 'limit',
      description: 'The maximum number of items to return. Defaults to 50 items.',
      in: 'query',
      schema: { type: ['integer', 'null'], minimum: 1, maximum: 250, example: 50 },
      required: false,
    },
    example: 50,
  })

