const BalanceIdParamsSchema = ((schema) =>
  z.union([schema, z.preprocess((val) => (val === 'null' ? null : val), schema)]))(
  z
    .string()
    .regex(/^bal_.+/)
    .nullable(),
)
  .exactOptional()
  .openapi({
    param: {
      name: 'balanceId',
      description:
        'Return only payouts for the balance with the given ID. The value must be a valid balance\ntoken in the format `bal_*`.',
      in: 'query',
      schema: {
        type: ['string', 'null'],
        pattern: '^bal_.+',
        example: 'bal_gVMhHKqSSRYJyPsuoPNFH',
      },
      required: false,
    },
    example: 'bal_gVMhHKqSSRYJyPsuoPNFH',
  })

const ParentPayoutIdParamsSchema = z
  .string()
  .openapi({
    param: {
      name: 'payoutId',
      description: 'Provide the ID of the payout.',
      in: 'path',
      required: true,
      schema: { type: 'string', example: 'payout_j8NvRAM2WNZtsykpLEX8J' },
    },
    example: 'payout_j8NvRAM2WNZtsykpLEX8J',
  })

const IdempotencyKeyParamsSchema = z
  .string()
  .exactOptional()
  .openapi({
    param: {
      name: 'idempotency-key',
      in: 'header',
      description:
        'A unique key to ensure idempotent requests. This key should be a UUID v4 string.',
      required: false,
      schema: { type: 'string', example: '123e4567-e89b-12d3-a456-426' },
    },
    example: '123e4567-e89b-12d3-a456-426',
  })

