export const postOauth2TokensRoute = createRoute({
  method: 'post',
  path: '/oauth2/tokens',
  tags: ['OAuth API'],
  summary: 'Generate tokens',
  description:
    "Exchange the authorization code you received from the [Authorize endpoint](oauth-authorize) for an 'access token'\nAPI credential, with which you can communicate with the Mollie API on behalf of the consenting merchant.\n\nThis endpoint can only be accessed using **OAuth client credentials**.",
  operationId: 'oauth-generate-tokens',
  request: {
    headers: z.object({
      Authorization: z
        .string()
        .openapi({
          param: {
            name: 'Authorization',
            description:
              'The OAuth client ID and client secret as\n[basic access credentials](https://en.wikipedia.org/wiki/Basic_access_authentication).\n\nPseudo code: `"Basic " + toBase64(client_id + ":" + client_secret)`\n\nFor example: `Basic QWxhZGRpbjpvcGVuIHNlc2FtZQ==`',
            in: 'header',
            schema: { type: 'string' },
            required: true,
          },
        }),
      'Content-Type': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'Content-Type',
            description:
              'This header value must match the type of the request body you send, if there is a request body. For example, if you send the request body as JSON, this header must be set to `application/json`, and if you send it as form encoded you must set this header to `application/x-www-form-urlencoded`.',
            in: 'header',
            schema: { type: 'string' },
            required: false,
          },
        }),
      'idempotency-key': IdempotencyKeyParamsSchema,
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              grant_type: OauthGrantTypeSchema.openapi({
                description:
                  'If you wish to exchange your authorization code for an app access token, use grant type\n`authorization_code`. If you wish to renew your app access token with your refresh token, use grant type\n`refresh_token`.',
              }),
              code: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'The authorization code you received when creating the authorization. Only use this field when using\ngrant type `authorization_code`.',
                  example: 'auth_...',
                }),
              refresh_token: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'The refresh token you received when creating the authorization. Only use this field when using grant\ntype `refresh_token`.',
                  example: 'refresh_...',
                }),
              redirect_uri: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'The URL the merchant is sent back to once the request has been authorized. It must match the URL you set\nwhen registering your app.',
                  example: 'https://example.com/redirect',
                }),
            })
            .openapi({ required: ['grant_type'] }),
        },
      },
    },
  },
  responses: {
    200: {
      description: 'The newly generated access token and refresh token.',
      content: {
        'application/json': {
          schema: z
            .object({
              access_token: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    "The app access token, with which you will be able to access the Mollie API on the merchant's behalf.",
                  example: 'access_...',
                }),
              refresh_token: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'The refresh token, with which you will be able to retrieve new app access tokens on this endpoint. The\nrefresh token does not expire.',
                  example: 'refresh_...',
                }),
              expires_in: z
                .int()
                .exactOptional()
                .openapi({
                  description:
                    'The number of seconds left before the app access token expires. Be sure to renew your app access token\nbefore this reaches zero.',
                  example: 3600,
                }),
              token_type: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'As per OAuth standards, the provided app access token can only be used with `bearer` authentication.\n\nPossible values: `bearer`',
                  example: 'bearer',
                }),
              scope: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'A space-separated list of [permissions](https://docs.mollie.com/docs/permissions).',
                  example: 'payments.read',
                }),
            })
            .openapi({ required: [] }),
          examples: {
            'oauth-generate-tokens': {
              summary: 'The newly generated access token and refresh token',
              value: {
                access_token: 'access_46EUJ6x8jFJZZeAvhNH4JVey6qVpqR',
                refresh_token: 'refresh_FS4xc3Mgci2xQ5s5DzaLXh3HhaTZOP',
                expires_in: 3600,
                token_type: 'bearer',
                scope: 'payments.read organizations.read',
              },
            },
          },
        },
      },
    },
    429: _429RateLimitResponse,
  },
  security: [{ basicAuth: [] }],
})

export const deleteOauth2TokensRoute = createRoute({
  method: 'delete',
  path: '/oauth2/tokens',
  tags: ['OAuth API'],
  summary: 'Revoke tokens',
  description:
    'Revoke an access token or refresh token. Once revoked, the token can no longer be used.\n\nRevoking a refresh token revokes all access tokens that were created using the same authorization.\n\nThis endpoint can only be accessed using **OAuth client credentials**.',
  operationId: 'oauth-revoke-tokens',
  request: {
    headers: z.object({
      Authorization: z
        .string()
        .openapi({
          param: {
            name: 'Authorization',
            description:
              'The OAuth client ID and client secret as\n[basic access credentials](https://en.wikipedia.org/wiki/Basic_access_authentication).\n\nPseudo code: `"Basic " + toBase64(client_id + ":" + client_secret)`\n\nFor example: `Basic QWxhZGRpbjpvcGVuIHNlc2FtZQ==`',
            in: 'header',
            schema: { type: 'string' },
            required: true,
          },
        }),
      'Content-Type': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'Content-Type',
            description:
              'This header value must match the type of the request body you send, if there is a request body. For example, if you send the request body as JSON, this header must be set to `application/json`, and if you send it as form encoded you must set this header to `application/x-www-form-urlencoded`.',
            in: 'header',
            schema: { type: 'string' },
            required: false,
          },
        }),
      'idempotency-key': IdempotencyKeyParamsSchema,
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              token_type_hint: OauthTokenTypeHintSchema.openapi({
                description: 'The type of token you want to revoke.',
              }),
              token: z
                .string()
                .openapi({ description: 'The token you want to revoke.', example: 'access_...' }),
            })
            .openapi({ required: ['token_type_hint', 'token'] }),
        },
      },
    },
  },
  responses: { 204: { description: 'An empty response.' }, 429: _429RateLimitResponse },
  security: [{ basicAuth: [] }],
})

