export const postV2PaymentsPaymentIdReleaseAuthorizationRoute = createRoute({
  method: 'post',
  path: '/v2/payments/{paymentId}/release-authorization',
  tags: ['Payments API'],
  summary: 'Release payment authorization',
  description:
    'Releases the full remaining authorized amount. Call this endpoint when you will not be making any additional\ncaptures. Payment authorizations may also be released manually from the Mollie Dashboard.\n\nMollie will do its best to process release requests, but it is not guaranteed that it will succeed. It is up to\nthe issuing bank if and when the hold will be released.\n\nIf the request does succeed, the payment status will change to `canceled` for payments without captures.\nIf there is a successful capture, the payment will transition to `paid`.',
  operationId: 'release-authorization',
  request: {
    params: z.object({ paymentId: ParentPaymentIdParamsSchema }),
    headers: z.object({ 'idempotency-key': IdempotencyKeyParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              profileId: ProfileIdSchema.exactOptional(),
              testmode: TestmodeCreateSchema.exactOptional(),
            })
            .openapi({ required: [] }),
        },
      },
    },
  },
  responses: {
    202: { description: 'The request was accepted and will be processed asynchronously.' },
    404: _404InvalidIdResponse,
    422: {
      description:
        'The request contains issues. For example, if you are trying to release a\npayment that that is not in an authorized state.',
      content: {
        'application/hal+json': {
          schema: ErrorResponseSchema,
          example: {
            status: 422,
            title: 'Unprocessable Entity',
            detail:
              'Authorization cannot be released because the payment is not in the authorized\nstate.',
            _links: { documentation: { href: '...', type: 'text/html' } },
          },
        },
      },
    },
    429: _429RateLimitResponse,
  },
  security: [
    { apiKey: [] },
    { advancedAccessToken: ['payments.write'] },
    { oAuth: ['payments.write'] },
  ],
})

