export const postV2CustomersCustomerIdSubscriptionsRoute = createRoute({
  method: 'post',
  path: '/v2/customers/{customerId}/subscriptions',
  tags: ['Subscriptions API'],
  summary: 'Create subscription',
  description:
    'With subscriptions, you can schedule recurring payments to take place at regular intervals.\n\nFor example, by simply specifying an `amount` and an `interval`, you can create an endless subscription to charge a\nmonthly fee, until you cancel the subscription.\n\nOr, you could use the times parameter to only charge a limited number of times, for example to split a big\ntransaction in multiple parts.\n\nA few example usages:\n\n`amount[currency]="EUR"` `amount[value]="5.00"` `interval="2 weeks"`\nYour customer will be charged €5 once every two weeks.\n\n`amount[currency]="EUR"` `amount[value]="20.00"` `interval="1 day" times=5`\nYour customer will be charged €20 every day, for five consecutive days.\n\n`amount[currency]="EUR"` `amount[value]="10.00"` `interval="1 month"`\n`startDate="2018-04-30"`\nYour customer will be charged €10 on the last day of each month, starting in April 2018.',
  operationId: 'create-subscription',
  request: {
    params: z.object({ customerId: ParentCustomerIdParamsSchema }),
    headers: z.object({ 'idempotency-key': IdempotencyKeyParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: SubscriptionRequestSchema.openapi({
            required: ['amount', 'interval', 'description'],
          }),
        },
      },
    },
  },
  responses: {
    201: {
      description: 'The newly created subscription object.',
      content: {
        'application/hal+json': {
          schema: SubscriptionResponseSchema,
          examples: { 'get-subscription-200-1': GetSubscriptionExample },
        },
      },
    },
    404: _404InvalidIdResponse,
    429: _429RateLimitResponse,
  },
  security: [
    { apiKey: [] },
    { advancedAccessToken: ['subscriptions.write'] },
    { oAuth: ['subscriptions.write'] },
  ],
})

