export const postV2BusinessAccountsTransfersRoute = createRoute({
  method: 'post',
  path: '/v2/business-accounts/transfers',
  tags: ['Transfers API'],
  summary: 'Create transfer',
  description:
    "> 🚧 Beta feature\n>\n> This feature is currently in beta testing, and the final specification may still change.\n\nCreate a SEPA Credit Transfer from your Mollie Business Account.\n\nTo initiate a transfer, you must provide the transfer scheme, the amount, the debtor IBAN (your Mollie Business\nAccount IBAN), and the creditor (recipient) details.\n\nEach request must include an `Idempotency-Key` header to prevent duplicate transfers, and must be signed using the\n`X-Client-Signature` and `X-Client-Signed-At` headers.\n\n### Simulating transfer scenarios in test mode\n\nIn test mode, you can simulate various transfer scenarios by adjusting the transfer amount. This allows you to\nmimic the typical status progression of a real-world transfer. Note that a transfer's progression will stop once\nit reaches a final status: `blocked`, `failed`, `processed`, or `returned`.\n\n| Amount  | Scenario                                            | Webhook sequence                                                                                                                                                   |\n|---------|-----------------------------------------------------|--------------------------------------------------------------------------------------------------------------------------------------------------------------------|\n| `11.00` | Transfer initiated, pending review by Mollie        | `business-account-transfer.requested` → `business-account-transfer.initiated` → `business-account-transfer.pending-review`                                         |\n| `12.00` | Transfer initiated, blocked by Mollie               | `business-account-transfer.requested` → `business-account-transfer.initiated` → `business-account-transfer.pending-review` → `business-account-transfer.blocked`   |\n| `13.00` | Transfer initiated, failed on scheme submission     | `business-account-transfer.requested` → `business-account-transfer.initiated` → `business-account-transfer.failed`                                                 |\n| `14.00` | Transfer processed, then returned by receiving bank | `business-account-transfer.requested` → `business-account-transfer.initiated` → `business-account-transfer.processed` → `business-account-transfer.returned`       |\n| Other   | Default: transfer is processed                      | `business-account-transfer.requested` → `business-account-transfer.initiated` → `business-account-transfer.processed`                                              |",
  operationId: 'create-transfer',
  request: {
    headers: z.object({
      'X-Client-Signature': z
        .string()
        .openapi({
          param: {
            name: 'X-Client-Signature',
            in: 'header',
            description:
              'A cryptographic signature of the request payload, used to verify the authenticity of the transfer request.',
            required: true,
            schema: { type: 'string' },
          },
        }),
      'X-Client-Signed-At': z
        .string()
        .openapi({
          param: {
            name: 'X-Client-Signed-At',
            in: 'header',
            description:
              'The timestamp (in ISO 8601 format) indicating when the client signed the request. Used in conjunction with\n`X-Client-Signature` for request verification.',
            required: true,
            schema: { type: 'string' },
            example: '2025-01-01T12:00:00Z',
          },
        }),
      'Idempotency-Key': z
        .string()
        .openapi({
          param: {
            name: 'Idempotency-Key',
            in: 'header',
            description:
              'A unique value used to identify this request and prevent duplicate transfers. UUIDv4 is recommended to\nguarantee uniqueness across multiple processes or servers. If two requests are received with the same\nidempotency key, the second request will be discarded.\n\nView the [public documentation](https://docs.mollie.com/reference/api-idempotency#using-an-idempotency-key)\nto learn more.',
            required: true,
            schema: { type: 'string' },
            example: '12345678-abcd',
          },
        }),
      'idempotency-key': IdempotencyKeyParamsSchema,
    }),
    body: { content: { 'application/json': { schema: TransferRequestSchema } } },
  },
  responses: {
    201: {
      description: 'The newly created transfer object.',
      content: {
        'application/hal+json': {
          schema: TransferResponseSchema,
          examples: { 'create-transfer-201': CreateTransferExample },
        },
      },
    },
    422: {
      description:
        'The request contains issues. For example, if the transfer amount is\nmissing, or if the debtor IBAN does not belong to your organization.',
      content: {
        'application/hal+json': {
          schema: ErrorResponseSchema,
          example: {
            status: 422,
            title: 'Unprocessable Entity',
            detail: "The 'creditor.account.iban' field is invalid",
            field: 'creditor.account.iban',
            _links: { documentation: { href: '...', type: 'text/html' } },
          },
        },
      },
    },
    429: _429RateLimitResponse,
    503: {
      description:
        'An unexpected error occurred on our end. This is not related to your request.\nPlease try again later. If the problem persists, contact support.',
      content: {
        'application/hal+json': {
          schema: ErrorResponseSchema,
          example: {
            status: 503,
            title: 'Service Unavailable',
            detail:
              'An unexpected error occurred while processing the transfer. Please try again later.',
            _links: { documentation: { href: '...', type: 'text/html' } },
          },
        },
      },
    },
  },
  security: [{ advancedAccessToken: ['business-account-transfers.write'] }],
})

